// src/products.ts
var PRODUCTS_URL = "https://api.jsoning.com/mock/public/products";
async function fetchProducts() {
  const res = await fetch(PRODUCTS_URL);
  const data = await res.json();
  if (Array.isArray(data)) return data;
  if (data.products) return data.products;
  return data.data || [];
}

// src/users.ts
var USERS_URL = "https://api.jsoning.com/mock/public/users";
async function fetchUsers() {
  const res = await fetch(USERS_URL);
  const data = await res.json();
  if (Array.isArray(data)) return data;
  return data.users || data.data || [];
}
function norm(s) {
  return (s || "").trim().toLowerCase();
}
function validateUserCredentials(users, email, username) {
  const e = norm(email);
  const u = norm(username);
  return users.find(
    (user) => norm(user.email) === e && norm(user.username) === u
  );
}
async function loginWithCredentials(email, username) {
  const users = await fetchUsers();
  const found = validateUserCredentials(users, email, username);
  if (!found) return null;
  const id = found.id ?? found._id ?? "1";
  return {
    token: `user-${id}`,
    user: found
  };
}
async function loginWithEmail(email) {
  return loginWithCredentials(email, "");
}

// src/carts.ts
import { STORAGE_KEYS } from "@org/contracts";
function readAll() {
  const raw = localStorage.getItem(STORAGE_KEYS.CART_DATA);
  if (!raw) return {};
  try {
    return JSON.parse(raw);
  } catch {
    return {};
  }
}
function writeAll(all) {
  localStorage.setItem(STORAGE_KEYS.CART_DATA, JSON.stringify(all));
}
function getCart(userId) {
  const all = readAll();
  return all[userId] || [];
}
function addToCart(userId, product) {
  const all = readAll();
  if (!all[userId]) all[userId] = [];
  const id = product.id ?? product._id;
  const existing = all[userId].find((i) => i.productId === id);
  if (existing) {
    existing.qty = (existing.qty || 1) + 1;
  } else {
    all[userId].push({
      productId: id,
      qty: 1,
      title: product.title || product.name,
      price: product.price,
      image: product.image || product.thumbnail
    });
  }
  writeAll(all);
  return all[userId];
}
function clearCart(userId) {
  const all = readAll();
  all[userId] = [];
  writeAll(all);
  return [];
}
var addToCartMock = addToCart;
var getCartFromStorage = getCart;

// src/orders.ts
import { STORAGE_KEYS as STORAGE_KEYS2 } from "@org/contracts";
var API_BASE = "http://localhost:3000/api/orders";
function readOrdersAll() {
  const raw = localStorage.getItem(STORAGE_KEYS2.ORDERS_DATA);
  if (!raw) return {};
  try {
    return JSON.parse(raw);
  } catch {
    return {};
  }
}
function writeOrdersAll(all) {
  localStorage.setItem(STORAGE_KEYS2.ORDERS_DATA, JSON.stringify(all));
}
function getOrdersLocal(userId) {
  const all = readOrdersAll();
  return all[userId] || [];
}
function saveOrdersLocal(userId, orders) {
  const all = readOrdersAll();
  all[userId] = orders;
  writeOrdersAll(all);
}
function calcTotal(items) {
  let t = 0;
  items.forEach((i) => {
    t += (i.price || 0) * (i.qty || 1);
  });
  return t;
}
async function placeOrder(userId, items) {
  const total = calcTotal(items);
  const order = {
    id: "ord-" + Date.now(),
    userId,
    createdAt: (/* @__PURE__ */ new Date()).toISOString(),
    items: [...items],
    total,
    status: "placed"
  };
  try {
    const res = await fetch(API_BASE, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ userId, items, total })
    });
    if (res.ok) {
      const saved = await res.json();
      order.id = saved.id || order.id;
      order.createdAt = saved.createdAt || order.createdAt;
    }
  } catch (e) {
    console.log("api order fail, saving local only", e);
  }
  const local = getOrdersLocal(userId);
  local.unshift(order);
  saveOrdersLocal(userId, local);
  clearCart(userId);
  return order;
}
async function fetchOrders(userId) {
  try {
    const res = await fetch(`${API_BASE}?userId=${encodeURIComponent(userId)}`);
    if (res.ok) {
      const data = await res.json();
      const list = Array.isArray(data) ? data : data.orders || [];
      if (list.length) {
        saveOrdersLocal(userId, list);
        return list;
      }
    }
  } catch (e) {
    console.log("fetch orders api failed", e);
  }
  return getOrdersLocal(userId);
}

